function lbShow(i){var s=curSet.list[i];cur=i;lbs.classList.remove('z');lbi.src=curSet.img[s.c][1];lbi.alt=s.c+' '+s.t;$('#lbc').innerHTML='<small>'+s.c+'</small>'+s.t;lbs.scrollTo(0,0)}
