function gShow(i){gi=i;var g=grp[i];cur=-1;lbs.classList.remove('z');lbi.src=g.src;lbi.alt=g.t;$('#lbc').textContent=(grp.length>1?(i+1)+' / '+grp.length+' · ':'')+g.t;lbs.scrollTo(0,0)}
function lbGrp(list,i){lastFocus=document.activeElement;grp=list;lb.classList.toggle('single',list.length<2);lb.hidden=false;document.body.style.overflow='hidden';gShow(i);$('.lbx',lb).focus()}
