function lbClose(){if(lb.hidden)return;grp=null;lb.hidden=true;lbi.removeAttribute('src');document.body.style.overflow='';if(lastFocus&&lastFocus.focus)lastFocus.focus()}
function lbStep(d){if(grp){gShow((gi+d+grp.length)%grp.length);return}var v=vis();if(!v.length)return;var k=v.indexOf(cur);lbShow(v[(k+d+v.length)%v.length])}
function tab(btn){var f=btn.dataset.tab;$$('[data-tab]').forEach(function(b){b.setAttribute('aria-pressed',b===btn?'true':'false')});$$('#sgrid .sh').forEach(function(e){e.hidden=!(f==='all'||e.dataset.k===f)})}
